// yinz-pi-agent-report v__VERSION__ - generated by yinz. Do not edit.
// Shared by inline launches and `yinz hocus hooks install --agent pi`.
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { randomUUID } from "node:crypto";

const YINZ_BIN = __YINZ_BIN__;
const PANE_TOKEN_ENV = __TOKEN_ENV__;
const TIMEOUT = 5000;

type Reporter = { owner?: symbol; reports: Promise<void> };
const globals = globalThis as typeof globalThis & { __yinz_pi_reporter?: Reporter };
// The queue survives runtime reloads so old reports cannot overtake new session reports.
const shared = globals.__yinz_pi_reporter ??= { reports: Promise.resolve() };

export default function (pi: ExtensionAPI): void {
  if (shared.owner) return;
  const owner = Symbol();
  shared.owner = owner;
  let deadline = Infinity;
  let cancel: (() => void) | undefined;
  let turn_id: string | undefined;
  let busy = false;
  let started = false;
  let waiting = false;
  let deferredCompletion: Record<string, unknown> | undefined;
  let lastAssistant: { text: string; stopReason?: string; errorMessage?: string } | undefined;

  function report(ctx: ExtensionContext, hook: Record<string, unknown>): void {
    if (ctx.mode !== "tui") return;
    // Parallel progress cannot dismiss an open dialog. Pi pairs overlapping dialogs for us.
    if (waiting && ["PreToolUse", "PostToolUse", "PostToolUseFailure", "PreCompact", "PostCompact"]
      .some(name => name === hook.hook_event_name)) hook.archive_only = true;
    const token = process.env[PANE_TOKEN_ENV];
    if (!token && !process.env.YINZ_PANE_ID) return;
    const args = token
      ? ["--pty-broker", "report", "pi"]
      : ["action", "agent-report", "--hook-json", "--kind", "pi"];
    let serialized: string;
    try { serialized = JSON.stringify(hook); } catch { return; }
    shared.reports = shared.reports.then(() => new Promise<void>((resolve) => {
      if (Date.now() >= deadline) { resolve(); return; }
      let child: ReturnType<typeof spawn>;
      try {
        child = spawn(existsSync(YINZ_BIN) ? YINZ_BIN : "yinz", args, {
          stdio: ["pipe", "ignore", "ignore"],
        });
      } catch { resolve(); return; }
      let done = false;
      const finish = (kill = false) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        cancel = undefined;
        if (kill) { try { child.kill("SIGKILL"); } catch {} }
        resolve();
      };
      const timer = setTimeout(() => finish(true), Math.min(TIMEOUT, deadline - Date.now()));
      cancel = () => finish(true);
      child.on("error", () => finish(true));
      child.on("close", () => finish());
      child.stdin?.on("error", () => finish(true));
      try { child.stdin?.end(serialized); } catch { finish(true); }
    })).catch(() => {});
  }

  function base(hook_event_name: string, ctx: ExtensionContext): Record<string, unknown> {
    return { hook_event_name, session_id: ctx.sessionManager.getSessionId(), cwd: ctx.cwd, turn_id };
  }
  function restore(hook: string, ctx: ExtensionContext, idle = !busy && ctx.isIdle()): void {
    report(ctx, { ...base(hook, ctx), source: idle ? "idle" : "busy" });
  }

  pi.on("session_start", (event, ctx) => {
    deferredCompletion = undefined;
    started = true;
    turn_id = undefined;
    busy = false;
    lastAssistant = undefined;
    const source = event.reason === "new" ? "clear" : event.reason === "reload" ? "startup" : event.reason;
    report(ctx, { ...base("SessionStart", ctx), source });
  });
  pi.on("before_agent_start", (event, ctx) => {
    deferredCompletion = undefined;
    turn_id = randomUUID();
    busy = true;
    lastAssistant = undefined;
    report(ctx, { ...base("UserPromptSubmit", ctx), prompt: event.prompt });
  });
  pi.on("tool_execution_start", (event, ctx) => {
    report(ctx, { ...base("PreToolUse", ctx), tool_name: event.toolName,
      tool_use_id: event.toolCallId, parent_tool_use_id: event.parentToolCallId, tool_input: event.args });
  });
  pi.on("tool_execution_end", (event, ctx) => {
    report(ctx, { ...base(event.isError ? "PostToolUseFailure" : "PostToolUse", ctx),
      tool_name: event.toolName, tool_use_id: event.toolCallId, parent_tool_use_id: event.parentToolCallId,
      tool_response: event.result, is_error: event.isError });
  });
  pi.on("message_end", (event) => {
    if (event.message.role !== "assistant") return;
    const message = event.message;
    lastAssistant = {
      text: message.content.filter(part => part.type === "text").map(part => part.text).join(""),
      stopReason: message.stopReason,
      errorMessage: message.errorMessage,
    };
  });
  pi.on("agent_settled", (_event, ctx) => {
    const hook = lastAssistant?.stopReason === "aborted" ? "Interrupt"
      : lastAssistant?.stopReason === "error" ? "StopFailure" : "Stop";
    const completion = { ...base(hook, ctx), last_assistant_message: lastAssistant?.text,
      message: lastAssistant?.errorMessage };
    if (waiting) deferredCompletion = completion;
    else report(ctx, completion);
    busy = false;
    turn_id = undefined;
    lastAssistant = undefined;
  });
  pi.on("ui_prompt_start", (event, ctx) => {
    if (!started) {
      started = true;
      report(ctx, { ...base("SessionStart", ctx), source: "startup" });
    }
    waiting = true;
    report(ctx, { ...base("Elicitation", ctx), message: event.title ?? `${event.kind} prompt` });
  });
  pi.on("ui_prompt_end", (_event, ctx) => {
    waiting = false;
    restore("ElicitationResult", ctx);
    if (deferredCompletion) {
      report(ctx, deferredCompletion);
      deferredCompletion = undefined;
    }
  });
  pi.on("session_before_compact", (_event, ctx) => report(ctx, base("PreCompact", ctx)));
  // Pi emits manual compaction results before clearing its compaction flag.
  pi.on("session_compact", (event, ctx) => {
    restore("PostCompact", ctx, event.reason === "manual" ? !busy : ctx.isIdle());
  });
  pi.on("session_compact_failed", (event, ctx) => {
    restore("PostCompact", ctx, event.reason === "manual" ? !busy : ctx.isIdle());
  });
  pi.on("session_shutdown", async (event, ctx) => {
    deferredCompletion = undefined;
    deadline = Date.now() + TIMEOUT;
    if (event.reason !== "reload") report(ctx, base("SessionEnd", ctx));
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
      await Promise.race([shared.reports, new Promise<void>(resolve => {
        timer = setTimeout(() => { cancel?.(); resolve(); }, TIMEOUT);
      })]);
    } finally {
      clearTimeout(timer);
      if (shared.owner === owner) shared.owner = undefined;
    }
  });
}
